"""Russian hover help. No document mutations, timers or enabled-state changes."""
from html import escape
from PySide6.QtCore import QObject, QEvent, Qt, QPoint
from PySide6.QtGui import QCursor
import weakref
from PySide6.QtWidgets import (QApplication, QWidget, QAbstractSpinBox, QLineEdit,
    QAbstractItemView, QTabBar, QToolTip, QScrollBar, QSplitterHandle, QGraphicsView)

DURATION = 15000
STYLE = "QToolTip { background-color:#172336; color:#ffffff; border:1px solid #93a7bf; padding:6px; font-family:'Segoe UI'; font-size:13px; }"


def rich(title, action, consequence):
    return ('<qt><table width="380" cellspacing="0" cellpadding="0"><tr><td>'
            f'<b>{escape(title)}</b><br>{escape(action)}<br><br>{escape(consequence)}</td></tr></table></qt>')


class HoverHelp(QObject):
    """Handle Qt's standard delayed ToolTip event even for disabled widgets.

    QApplication's filter precedes disabled QWidget event handling. Use the
    native style's hover delay; never synthesize hover with a polling timer.
    """
    def __init__(self, parent=None):
        super().__init__(parent)
        self._target = None
        self._text = ""
        self._rect = None

    def _dismiss_if_outside(self):
        if self._target is None or not QToolTip.isVisible(): return
        target = self._target()
        try:
            inside = target is not None and target.isVisible() and self._rect.contains(target.mapFromGlobal(QCursor.pos()))
        except RuntimeError:
            inside = False
        if not inside:
            QToolTip.hideText()
            self._target = None

    def eventFilter(self, watched, event):
        if event.type() in (QEvent.Type.MouseMove, QEvent.Type.Enter, QEvent.Type.Leave):
            self._dismiss_if_outside()
        elif event.type() in (QEvent.Type.MouseButtonPress, QEvent.Type.KeyPress, QEvent.Type.Wheel):
            QToolTip.hideText()
            self._target = None
        elif event.type() in (QEvent.Type.WindowDeactivate, QEvent.Type.Hide):
            if self._target is not None:
                target = self._target()
                try:
                    if target is not None and watched is target.window():
                        QToolTip.hideText(); self._target = None
                except RuntimeError:
                    self._target = None
        if event.type() != QEvent.Type.ToolTip or not isinstance(watched, QWidget):
            return False
        if not watched.window().property("pbnHoverHelp"):
            return False
        target, text, rect = watched, "", watched.rect()
        if isinstance(target, QTabBar):
            index = target.tabAt(event.pos())
            if index >= 0:
                text, rect = target.tabToolTip(index), target.tabRect(index)
        view = target if isinstance(target, QAbstractItemView) else target.parentWidget()
        if isinstance(view, QAbstractItemView):
            viewport = view.viewport()
            position = viewport.mapFrom(watched, event.pos())
            index = view.indexAt(position)
            if index.isValid():
                text = index.data(Qt.ItemDataRole.ToolTipRole) or text
                if text:
                    target, rect = viewport, view.visualRect(index)
        if isinstance(view, QGraphicsView):
            position = view.viewport().mapFrom(watched, event.pos())
            item = view.itemAt(position)
            if item is not None and item.toolTip():
                target, text = view.viewport(), item.toolTip()
                rect = view.mapFromScene(item.sceneBoundingRect()).boundingRect()
        # Never walk arbitrary ancestors: empty canvas/list space is not help.
        if isinstance(view, (QAbstractItemView, QGraphicsView)) and not text:
            event.accept()
            return True
        if not text:
            text = target.toolTip()
        # Spinbox editors and arrows are one logical help target.
        if target is not None and isinstance(target.parentWidget(), QAbstractSpinBox):
            parent = target.parentWidget()
            if text == parent.toolTip():
                target, rect = parent, parent.rect()
        if text and target is not None and target.window().property("pbnHoverHelp"):
            same = (self._target is not None and self._target() is target
                    and self._text == text and self._rect == rect)
            # Qt owns duration; logical target owns dismissal. Never reposition a
            # visible tip for repeated events inside the same logical target.
            if not (same and QToolTip.isVisible() and QToolTip.text() == text):
                anchor = target.mapToGlobal(QPoint(rect.left(), rect.bottom() + 7))
                QToolTip.showText(anchor, text, target, rect, DURATION)
                # Qt's global QTipLabel filter treats every child Leave as exit,
                # even when the pointer remains inside one logical spin control.
                # Keep native delay/duration/rendering; own only dismissal using
                # the logical target rectangle and real pointer/input events.
                app = QApplication.instance()
                for popup in app.topLevelWidgets():
                    if popup.metaObject().className() == "QTipLabel" and popup.isVisible():
                        app.removeEventFilter(popup)
                self._target, self._text, self._rect = weakref.ref(target), text, rect
            event.accept()
            return True
        return False


def install(window):
    app = QApplication.instance()
    if not hasattr(app, "_pbn_hover_help"):
        app._pbn_hover_help = HoverHelp(app)
        app.installEventFilter(app._pbn_hover_help)
        app.setStyleSheet(app.styleSheet() + "\n" + STYLE)
    window.setProperty("pbnHoverHelp", True)
    window.setAttribute(Qt.WidgetAttribute.WA_AlwaysShowToolTips, True)


def set_tip(widget, title, action, consequence):
    text = rich(title, action, consequence)
    widget.setToolTip(text)
    widget.setToolTipDuration(DURATION)
    if isinstance(widget, QAbstractSpinBox):
        widget.lineEdit().setToolTip(text)
        widget.lineEdit().setToolTipDuration(DURATION)
    return text


