def navigation_help(root):
    for widget in root.findChildren(QWidget):
        if isinstance(widget, QScrollBar):
            set_tip(widget, "Прокрутка", "Переместить видимую часть изображения или списка по направлению полосы.", "Содержимое документа не меняется. В двух основных изображениях положение и масштаб синхронизированы.")
        elif widget.objectName() in ("ScrollLeftButton", "ScrollRightButton"):
            set_tip(widget, "Прокрутка вкладок", "Показать скрытые вкладки слева или справа, если для них не хватает места в окне.", "Меняется только видимая часть панели вкладок, не изображение и не параметры печати.")
        elif isinstance(widget, QSplitterHandle):
            set_tip(widget, "Ширина предпросмотра", "Перетащите разделитель, чтобы изменить место для левого и правого изображения.", "Изменяется только компоновка окна: размеры рисунка и параметры печати сохраняются.")


def setup_main(window):
    install(window)
    for name, text in MAIN.items():
        if name not in ("issue_list", "batch_report_list"):
            set_tip(getattr(window, name), *text)
    for button in window.findChildren(QWidget):
        if hasattr(button, "text") and callable(button.text):
            if button.text() == "Вписать":
                set_tip(button, "Вписать изображение", "Подобрать масштаб так, чтобы весь результат помещался в окне; без документа вписывается исходник.", "Оба вида синхронизированы. Меняется только просмотр, а не размер печатного листа и не качество изображения.")
            elif button.text() == "100 %":
                set_tip(button, "Масштаб 100 %", "Установить масштаб результата 1:1 относительно координат исходного изображения, сохранив центр просмотра.", "Второй вид синхронизируется. Это не физический размер отпечатка: масштаб Windows и плотность экрана могут отличаться от печати.")
    for i, text in enumerate(TOOLS):
        window.tool_combo.setItemData(i, rich(*text), Qt.ItemDataRole.ToolTipRole)
    def selected_mode(index):
        set_tip(window.tool_combo, *TOOLS[index])
    selected_mode(window.tool_combo.currentIndex())
    window.tool_combo.currentIndexChanged.connect(selected_mode)
    set_tip(window.mode_tabs, "Режим просмотра", "Переключить правый вид между цветным ответом, контурами и номерами.", "Это не изменение документа. Настройки печати и исходник остаются прежними; проверка перед экспортом действует в каждом режиме.")
    for i, text in enumerate(TABS):
        window.mode_tabs.setTabToolTip(i, rich(*text))



