def setup_dialog(dialog):
    from PySide6.QtWidgets import QAbstractButton, QGraphicsView
    install(dialog)
    for button in dialog.findChildren(QAbstractButton):
        text = DIALOG_BUTTONS.get(button.text())
        if text: set_tip(button, *text)
